(window.__quranSurahs=window.__quranSurahs||{})[109]={"nomPhon":"Al-Kaafiroon","versets":{"1":{"text":"Dis: «O vous les infidèles!","arabe":"قُلْ يَٰٓأَيُّهَا ٱلْكَٰفِرُونَ"},"2":{"text":"Je n'adore pas ce que vous adorez.","arabe":"لَآ أَعْبُدُ مَا تَعْبُدُونَ"},"3":{"text":"Et vous n'êtes pas adorateurs de ce que j'adore.","arabe":"وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ"},"4":{"text":"Je ne suis pas adorateur de ce que vous adorez.","arabe":"وَلَآ أَنَا۠ عَابِدٌۭ مَّا عَبَدتُّمْ"},"5":{"text":"Et vous n'êtes pas adorateurs de ce que j'adore.","arabe":"وَلَآ أَنتُمْ عَٰبِدُونَ مَآ أَعْبُدُ"},"6":{"text":"A vous votre religion, et à moi ma religion».","arabe":"لَكُمْ دِينُكُمْ وَلِىَ دِينِ"}}};